915	bool SocketCore::tlsHandshake(TLSContext* tlsctx, const std::string& hostname)
916	{
917	  wantRead_ = false;
918	  wantWrite_ = false;
919	
920	  if (secure_ == A2_TLS_CONNECTED) {
921	    // Already connected!
922	    return true;
923	  }
924	
925	  if (secure_ == A2_TLS_NONE) {
926	    // Do some initial setup
927	    A2_LOG_DEBUG("Creating TLS session");
928	    tlsSession_.reset(TLSSession::make(tlsctx));
929	    auto rv = tlsSession_->init(sockfd_);
930	    if (rv != TLS_ERR_OK) {
931	      std::string error = tlsSession_->getLastErrorString();
932	      tlsSession_.reset();
933	      throw DL_ABORT_EX(fmt(EX_SSL_INIT_FAILURE, error.c_str()));
934	    }
935	    // Check hostname is not numeric and it includes ".". Setting
936	    // "localhost" will produce TLS alert with GNUTLS.
937	    if (tlsctx->getSide() == TLS_CLIENT && !util::isNumericHost(hostname) &&
938	        hostname.find(".") != std::string::npos) {
939	      rv = tlsSession_->setSNIHostname(hostname);
940	      if (rv != TLS_ERR_OK) {
941	        throw DL_ABORT_EX(fmt(EX_SSL_INIT_FAILURE,
942	                              tlsSession_->getLastErrorString().c_str()));
943	      }
944	    }
945	    // Done with the setup, now let handshaking begin immediately.
946	    secure_ = A2_TLS_HANDSHAKING;
947	    A2_LOG_DEBUG("TLS Handshaking");
948	  }
949	
950	  if (secure_ == A2_TLS_HANDSHAKING) {
951	    // Starting handshake after initial setup or still handshaking.
952	    TLSVersion ver = TLS_PROTO_NONE;
953	    int rv = 0;
954	    std::string handshakeError;
955	
956	    if (tlsctx->getSide() == TLS_CLIENT) {
957	      rv = tlsSession_->tlsConnect(hostname, ver, handshakeError);
958	    }
959	    else {
960	      rv = tlsSession_->tlsAccept(ver);
961	    }
962	
963	    if (rv == TLS_ERR_OK) {
964	      // We're good, more or less.
965	      // 1. Construct peerinfo
966	      std::stringstream ss;
967	      if (!hostname.empty()) {
968	        ss << hostname << " (";
969	      }
970	      auto peerEndpoint = getPeerInfo();
971	      ss << peerEndpoint.addr << ":" << peerEndpoint.port;
972	      if (!hostname.empty()) {
973	        ss << ")";
974	      }
975	
976	      std::string tlsVersion;
977	      switch (ver) {
978	      case TLS_PROTO_TLS11:
979	        tlsVersion = A2_V_TLS11;
980	        break;
981	      case TLS_PROTO_TLS12:
982	        tlsVersion = A2_V_TLS12;
983	        break;
984	      case TLS_PROTO_TLS13:
985	        tlsVersion = A2_V_TLS13;
986	        break;
987	      default:
988	        assert(0);
989	        abort();
990	      }
991	
992	      auto peerInfo = ss.str();
993	
994	      A2_LOG_DEBUG(fmt("Securely connected to %s with %s", peerInfo.c_str(),
995	                       tlsVersion.c_str()));
996	
997	      // 2. We're connected now!
998	      secure_ = A2_TLS_CONNECTED;
999	      return true;
1000	    }
1001	
1002	    if (rv == TLS_ERR_WOULDBLOCK) {
1003	      // We're not done yet...
1004	      if (tlsSession_->checkDirection() == TLS_WANT_READ) {
1005	        // ... but read buffers are empty.
1006	        wantRead_ = true;
1007	      }
1008	      else {
1009	        // ... but write buffers are full.
1010	        wantWrite_ = true;
1011	      }
1012	      // Returning false (instead of true==success or throwing) will cause this
1013	      // function to be called again once buffering is dealt with
1014	      return false;
1015	    }
1016	
1017	    if (rv == TLS_ERR_ERROR) {
1018	      // Damn those error.
1019	      throw DL_ABORT_EX(fmt("SSL/TLS handshake failure: %s",
1020	                            handshakeError.empty()
1021	                                ? tlsSession_->getLastErrorString().c_str()
1022	                                : handshakeError.c_str()));
1023	    }
1024	
1025	    // Some implementation passed back an invalid result.
1026	    throw DL_ABORT_EX(fmt(EX_SSL_INIT_FAILURE,
1027	                          "Invalid connect state (this is a bug in the TLS "
1028	                          "backend!)"));
1029	  }
1030	
1031	  // We should never get here, i.e. all possible states should have been handled
1032	  // and returned from a branch before! Getting here is a bug, of course!
1033	  throw DL_ABORT_EX(fmt(EX_SSL_INIT_FAILURE, "Invalid state (this is a bug!)"));
1034	}
