1040	bool SocketCore::sshHandshake(const std::string& hashType,
1041	                              const std::string& digest)
1042	{
1043	  wantRead_ = false;
1044	  wantWrite_ = false;
1045	
1046	  if (!sshSession_) {
1047	    sshSession_ = make_unique<SSHSession>();
1048	    if (sshSession_->init(sockfd_) == SSH_ERR_ERROR) {
1049	      throw DL_ABORT_EX("Could not create SSH session");
1050	    }
1051	  }
1052	  auto rv = sshSession_->handshake();
1053	  if (rv == SSH_ERR_WOULDBLOCK) {
1054	    sshCheckDirection();
1055	    return false;
1056	  }
1057	  if (rv == SSH_ERR_ERROR) {
1058	    throw DL_ABORT_EX(fmt("SSH handshake failure: %s",
1059	                          sshSession_->getLastErrorString().c_str()));
1060	  }
1061	  if (!hashType.empty()) {
1062	    auto actualDigest = sshSession_->hostkeyMessageDigest(hashType);
1063	    if (actualDigest.empty()) {
1064	      throw DL_ABORT_EX(fmt("Empty host key fingerprint from SSH layer: "
1065	                            "perhaps hash type %s is not supported?",
1066	                            hashType.c_str()));
1067	    }
1068	    if (digest != actualDigest) {
1069	      throw DL_ABORT_EX(fmt("Unexpected SSH host key: expected %s, actual %s",
1070	                            util::toHex(digest).c_str(),
1071	                            util::toHex(actualDigest).c_str()));
1072	    }
1073	  }
1074	  return true;
1075	}
