1189	ssize_t SocketCore::writeData(const void* data, size_t len,
1190	                              const std::string& host, uint16_t port)
1191	{
1192	  wantRead_ = false;
1193	  wantWrite_ = false;
1194	
1195	  struct addrinfo* res;
1196	  int s;
1197	  s = callGetaddrinfo(&res, host.c_str(), util::uitos(port).c_str(),
1198	                      protocolFamily_, sockType_, 0, 0);
1199	  if (s) {
1200	    throw DL_ABORT_EX(fmt(EX_SOCKET_SEND, gai_strerror(s)));
1201	  }
1202	  std::unique_ptr<addrinfo, decltype(&freeaddrinfo)> resDeleter(res,
1203	                                                                freeaddrinfo);
1204	  struct addrinfo* rp;
1205	  ssize_t r = -1;
1206	  int errNum = 0;
1207	  for (rp = res; rp; rp = rp->ai_next) {
1208	    // Cast for Windows sendto()
1209	    while ((r = sendto(sockfd_, reinterpret_cast<const char*>(data), len, 0,
1210	                       rp->ai_addr, rp->ai_addrlen)) == -1 &&
1211	           A2_EINTR == SOCKET_ERRNO)
1212	      ;
1213	    errNum = SOCKET_ERRNO;
1214	    if (r == static_cast<ssize_t>(len)) {
1215	      break;
1216	    }
1217	    if (r == -1 && A2_WOULDBLOCK(errNum)) {
1218	      wantWrite_ = true;
1219	      r = 0;
1220	      break;
1221	    }
1222	  }
1223	  if (r == -1) {
1224	    throw DL_ABORT_EX(fmt(EX_SOCKET_SEND, errorMsg(errNum).c_str()));
1225	  }
1226	  return r;
1227	}
