1229	ssize_t SocketCore::readDataFrom(void* data, size_t len, Endpoint& sender)
1230	{
1231	  wantRead_ = false;
1232	  wantWrite_ = false;
1233	  sockaddr_union sockaddr;
1234	  socklen_t sockaddrlen = sizeof(sockaddr);
1235	  ssize_t r;
1236	  // Cast for Windows recvfrom()
1237	  while ((r = recvfrom(sockfd_, reinterpret_cast<char*>(data), len, 0,
1238	                       &sockaddr.sa, &sockaddrlen)) == -1 &&
1239	         A2_EINTR == SOCKET_ERRNO)
1240	    ;
1241	  int errNum = SOCKET_ERRNO;
1242	  if (r == -1) {
1243	    if (!A2_WOULDBLOCK(errNum)) {
1244	      throw DL_RETRY_EX(fmt(EX_SOCKET_RECV, errorMsg(errNum).c_str()));
1245	    }
1246	    wantRead_ = true;
1247	    r = 0;
1248	  }
1249	  else {
1250	    sender = util::getNumericNameInfo(&sockaddr.sa, sockaddrlen);
1251	  }
1252	
1253	  return r;
1254	}
