1350	std::vector<SockAddr> SocketCore::getInterfaceAddress(const std::string& iface,
1351	                                                      int family, int aiFlags)
1352	{
1353	  A2_LOG_DEBUG(fmt("Finding interface %s", iface.c_str()));
1354	  std::vector<SockAddr> ifAddrs;
1355	#ifdef HAVE_GETIFADDRS
1356	  // First find interface in interface addresses
1357	  struct ifaddrs* ifaddr = nullptr;
1358	  if (getifaddrs(&ifaddr) == -1) {
1359	    int errNum = SOCKET_ERRNO;
1360	    A2_LOG_INFO(
1361	        fmt(MSG_INTERFACE_NOT_FOUND, iface.c_str(), errorMsg(errNum).c_str()));
1362	  }
1363	  else {
1364	    std::unique_ptr<ifaddrs, decltype(&freeifaddrs)> ifaddrDeleter(ifaddr,
1365	                                                                   freeifaddrs);
1366	    for (ifaddrs* ifa = ifaddr; ifa; ifa = ifa->ifa_next) {
1367	      if (!ifa->ifa_addr) {
1368	        continue;
1369	      }
1370	      int iffamily = ifa->ifa_addr->sa_family;
1371	      if (family == AF_UNSPEC) {
1372	        if (iffamily != AF_INET && iffamily != AF_INET6) {
1373	          continue;
1374	        }
1375	      }
1376	      else if (family == AF_INET) {
1377	        if (iffamily != AF_INET) {
1378	          continue;
1379	        }
1380	      }
1381	      else if (family == AF_INET6) {
1382	        if (iffamily != AF_INET6) {
1383	          continue;
1384	        }
1385	      }
1386	      else {
1387	        continue;
1388	      }
1389	      if (strcmp(iface.c_str(), ifa->ifa_name) == 0) {
1390	        SockAddr soaddr;
1391	        soaddr.suLength =
1392	            iffamily == AF_INET ? sizeof(sockaddr_in) : sizeof(sockaddr_in6);
1393	        memcpy(&soaddr.su, ifa->ifa_addr, soaddr.suLength);
1394	        ifAddrs.push_back(soaddr);
1395	      }
1396	    }
1397	  }
1398	#endif // HAVE_GETIFADDRS
1399	  if (ifAddrs.empty()) {
1400	    addrinfo* res;
1401	    int s;
1402	    s = callGetaddrinfo(&res, iface.c_str(), nullptr, family, SOCK_STREAM,
1403	                        aiFlags, 0);
1404	    if (s) {
1405	      A2_LOG_INFO(fmt(MSG_INTERFACE_NOT_FOUND, iface.c_str(), gai_strerror(s)));
1406	    }
1407	    else {
1408	      std::unique_ptr<addrinfo, decltype(&freeaddrinfo)> resDeleter(
1409	          res, freeaddrinfo);
1410	      addrinfo* rp;
1411	      for (rp = res; rp; rp = rp->ai_next) {
1412	        // Try to bind socket with this address. If it fails, the
1413	        // address is not for this machine.
1414	        try {
1415	          SocketCore socket;
1416	          socket.bind(rp->ai_addr, rp->ai_addrlen);
1417	          SockAddr soaddr;
1418	          memcpy(&soaddr.su, rp->ai_addr, rp->ai_addrlen);
1419	          soaddr.suLength = rp->ai_addrlen;
1420	          ifAddrs.push_back(soaddr);
1421	        }
1422	        catch (RecoverableException& e) {
1423	          continue;
1424	        }
1425	      }
1426	    }
1427	  }
1428	
1429	  return ifAddrs;
1430	}
