1442	int callGetaddrinfo(struct addrinfo** resPtr, const char* host,
1443	                    const char* service, int family, int sockType, int flags,
1444	                    int protocol)
1445	{
1446	  struct addrinfo hints;
1447	  memset(&hints, 0, sizeof(hints));
1448	  hints.ai_family = family;
1449	  hints.ai_socktype = sockType;
1450	  hints.ai_flags = getDefaultAIFlags();
1451	  hints.ai_flags |= flags;
1452	  hints.ai_protocol = protocol;
1453	  return getaddrinfo(host, service, &hints, resPtr);
