1456	int inetNtop(int af, const void* src, char* dst, socklen_t size)
1457	{
1458	  sockaddr_union su;
1459	  memset(&su, 0, sizeof(su));
1460	  if (af == AF_INET) {
1461	    su.in.sin_family = AF_INET;
1462	#ifdef HAVE_SOCKADDR_IN_SIN_LEN
1463	    su.in.sin_len = sizeof(su.in);
1464	#endif // HAVE_SOCKADDR_IN_SIN_LEN
1465	    memcpy(&su.in.sin_addr, src, sizeof(su.in.sin_addr));
1466	    return getnameinfo(&su.sa, sizeof(su.in), dst, size, nullptr, 0,
1467	                       NI_NUMERICHOST);
1468	  }
1469	  if (af == AF_INET6) {
1470	    su.in6.sin6_family = AF_INET6;
1471	#ifdef HAVE_SOCKADDR_IN6_SIN6_LEN
1472	    su.in6.sin6_len = sizeof(su.in6);
1473	#endif // HAVE_SOCKADDR_IN6_SIN6_LEN
1474	    memcpy(&su.in6.sin6_addr, src, sizeof(su.in6.sin6_addr));
1475	    return getnameinfo(&su.sa, sizeof(su.in6), dst, size, nullptr, 0,
1476	                       NI_NUMERICHOST);
1477	  }
1478	  return EAI_FAMILY;
1479	}
