1481	int inetPton(int af, const char* src, void* dst)
1482	{
1483	  union {
1484	    uint32_t ipv4_addr;
1485	    unsigned char ipv6_addr[16];
1486	  } binaddr;
1487	  size_t len = net::getBinAddr(binaddr.ipv6_addr, src);
1488	  if (af == AF_INET) {
1489	    if (len != 4) {
1490	      return -1;
1491	    }
1492	    in_addr* addr = reinterpret_cast<in_addr*>(dst);
1493	    addr->s_addr = binaddr.ipv4_addr;
1494	    return 0;
1495	  }
1496	  if (af == AF_INET6) {
1497	    if (len != 16) {
1498	      return -1;
1499	    }
1500	    in6_addr* addr = reinterpret_cast<in6_addr*>(dst);
1501	    memcpy(addr->s6_addr, binaddr.ipv6_addr, sizeof(addr->s6_addr));
1502	    return 0;
1503	  }
1504	  return -1;
1505	}
