1509	size_t getBinAddr(void* dest, const std::string& ip)
1510	{
1511	  size_t len = 0;
1512	  addrinfo* res;
1513	  if (callGetaddrinfo(&res, ip.c_str(), nullptr, AF_UNSPEC, 0, AI_NUMERICHOST,
1514	                      0) != 0) {
1515	    return len;
1516	  }
1517	  std::unique_ptr<addrinfo, decltype(&freeaddrinfo)> resDeleter(res,
1518	                                                                freeaddrinfo);
1519	  for (addrinfo* rp = res; rp; rp = rp->ai_next) {
1520	    sockaddr_union su;
1521	    memcpy(&su, rp->ai_addr, rp->ai_addrlen);
1522	    if (rp->ai_family == AF_INET) {
1523	      len = sizeof(in_addr);
1524	      memcpy(dest, &(su.in.sin_addr), len);
1525	      break;
1526	    }
1527	    else if (rp->ai_family == AF_INET6) {
1528	      len = sizeof(in6_addr);
1529	      memcpy(dest, &(su.in6.sin6_addr), len);
1530	      break;
1531	    }
1532	  }
1533	  return len;
1534	}
