1536	bool verifyHostname(const std::string& hostname,
1537	                    const std::vector<std::string>& dnsNames,
1538	                    const std::vector<std::string>& ipAddrs,
1539	                    const std::string& commonName)
1540	{
1541	  if (util::isNumericHost(hostname)) {
1542	    if (ipAddrs.empty()) {
1543	      return commonName == hostname;
1544	    }
1545	    // We need max 16 bytes to store IPv6 address.
1546	    unsigned char binAddr[16];
1547	    size_t addrLen = getBinAddr(binAddr, hostname);
1548	    if (addrLen == 0) {
1549	      return false;
1550	    }
1551	    for (auto& ipAddr : ipAddrs) {
1552	      if (addrLen == ipAddr.size() &&
1553	          memcmp(binAddr, ipAddr.c_str(), addrLen) == 0) {
1554	        return true;
1555	      }
1556	    }
1557	    return false;
1558	  }
1559	
1560	  if (dnsNames.empty()) {
1561	    return util::tlsHostnameMatch(commonName, hostname);
1562	  }
1563	  for (auto& dnsName : dnsNames) {
1564	    if (util::tlsHostnameMatch(dnsName, hostname)) {
1565	      return true;
1566	    }
1567	  }
1568	  return false;
1569	}
