1573	bool ipv6AddrConfigured = true;
1574	} // namespace
1575	
1576	#ifdef __MINGW32__
1577	namespace {
1578	const uint32_t APIPA_IPV4_BEGIN = 2851995649u; // 169.254.0.1
1579	const uint32_t APIPA_IPV4_END = 2852061183u;   // 169.254.255.255
1580	} // namespace
1581	#endif // __MINGW32__
1582	
1583	void checkAddrconfig()
1584	{
1585	#ifdef HAVE_IPHLPAPI_H
1586	  A2_LOG_INFO("Checking configured addresses");
1587	  ULONG bufsize = 15_k;
1588	  ULONG retval = 0;
1589	  IP_ADAPTER_ADDRESSES* buf = 0;
1590	  int numTry = 0;
1591	  const int MAX_TRY = 3;
1592	  do {
1593	    buf = reinterpret_cast<IP_ADAPTER_ADDRESSES*>(malloc(bufsize));
1594	    retval = GetAdaptersAddresses(AF_UNSPEC, 0, 0, buf, &bufsize);
1595	    if (retval != ERROR_BUFFER_OVERFLOW) {
1596	      break;
1597	    }
1598	    free(buf);
1599	    buf = 0;
1600	  } while (retval == ERROR_BUFFER_OVERFLOW && numTry < MAX_TRY);
1601	  if (retval != NO_ERROR) {
1602	    A2_LOG_INFO("GetAdaptersAddresses failed. Assume both IPv4 and IPv6 "
1603	                " addresses are configured.");
1604	    return;
1605	  }
1606	  ipv4AddrConfigured = false;
1607	  ipv6AddrConfigured = false;
1608	  char host[NI_MAXHOST];
1609	  sockaddr_union ad;
1610	  int rv;
1611	  for (IP_ADAPTER_ADDRESSES* p = buf; p; p = p->Next) {
1612	    if (p->IfType == IF_TYPE_TUNNEL) {
1613	      // Skip tunnel interface because Windows7 automatically setup
1614	      // this for IPv6.
1615	      continue;
1616	    }
1617	    PIP_ADAPTER_UNICAST_ADDRESS ucaddr = p->FirstUnicastAddress;
1618	    if (!ucaddr) {
1619	      continue;
1620	    }
1621	    for (PIP_ADAPTER_UNICAST_ADDRESS i = ucaddr; i; i = i->Next) {
1622	      bool found = false;
1623	      switch (i->Address.iSockaddrLength) {
1624	      case sizeof(sockaddr_in): {
1625	        memcpy(&ad.storage, i->Address.lpSockaddr, i->Address.iSockaddrLength);
1626	        uint32_t haddr = ntohl(ad.in.sin_addr.s_addr);
1627	        if (haddr != INADDR_LOOPBACK &&
1628	            (haddr < APIPA_IPV4_BEGIN || APIPA_IPV4_END <= haddr)) {
1629	          ipv4AddrConfigured = true;
1630	          found = true;
1631	        }
1632	        break;
1633	      }
1634	      case sizeof(sockaddr_in6):
1635	        memcpy(&ad.storage, i->Address.lpSockaddr, i->Address.iSockaddrLength);
1636	        if (!IN6_IS_ADDR_LOOPBACK(&ad.in6.sin6_addr) &&
1637	            !IN6_IS_ADDR_LINKLOCAL(&ad.in6.sin6_addr)) {
1638	          ipv6AddrConfigured = true;
1639	          found = true;
1640	        }
1641	        break;
1642	      }
1643	      rv = getnameinfo(i->Address.lpSockaddr, i->Address.iSockaddrLength, host,
1644	                       NI_MAXHOST, 0, 0, NI_NUMERICHOST);
1645	      if (rv == 0) {
1646	        if (found) {
1647	          A2_LOG_INFO(fmt("Found configured address: %s", host));
1648	        }
1649	        else {
1650	          A2_LOG_INFO(fmt("Not considered: %s", host));
1651	        }
1652	      }
1653	    }
1654	  }
1655	  free(buf);
1656	
1657	  A2_LOG_INFO(fmt("IPv4 configured=%d, IPv6 configured=%d", ipv4AddrConfigured,
1658	                  ipv6AddrConfigured));
1659	#elif defined(HAVE_GETIFADDRS)
1660	  A2_LOG_INFO("Checking configured addresses");
1661	  ipv4AddrConfigured = false;
1662	  ipv6AddrConfigured = false;
1663	  ifaddrs* ifaddr = nullptr;
1664	  int rv;
1665	  rv = getifaddrs(&ifaddr);
1666	  if (rv == -1) {
1667	    int errNum = SOCKET_ERRNO;
1668	    A2_LOG_INFO(fmt("getifaddrs failed. Cause: %s", errorMsg(errNum).c_str()));
1669	    return;
1670	  }
1671	  std::unique_ptr<ifaddrs, decltype(&freeifaddrs)> ifaddrDeleter(ifaddr,
1672	                                                                 freeifaddrs);
1673	  char host[NI_MAXHOST];
1674	  sockaddr_union ad;
1675	  for (ifaddrs* ifa = ifaddr; ifa; ifa = ifa->ifa_next) {
1676	    if (!ifa->ifa_addr) {
1677	      continue;
1678	    }
1679	    bool found = false;
1680	    size_t addrlen = 0;
1681	    switch (ifa->ifa_addr->sa_family) {
1682	    case AF_INET: {
1683	      addrlen = sizeof(sockaddr_in);
1684	      memcpy(&ad.storage, ifa->ifa_addr, addrlen);
1685	      if (ad.in.sin_addr.s_addr != htonl(INADDR_LOOPBACK)) {
1686	        ipv4AddrConfigured = true;
1687	        found = true;
1688	      }
1689	      break;
1690	    }
1691	    case AF_INET6: {
1692	      addrlen = sizeof(sockaddr_in6);
1693	      memcpy(&ad.storage, ifa->ifa_addr, addrlen);
1694	      if (!IN6_IS_ADDR_LOOPBACK(&ad.in6.sin6_addr) &&
1695	          !IN6_IS_ADDR_LINKLOCAL(&ad.in6.sin6_addr)) {
1696	        ipv6AddrConfigured = true;
1697	        found = true;
1698	      }
1699	      break;
1700	    }
1701	    default:
1702	      continue;
1703	    }
1704	    rv = getnameinfo(ifa->ifa_addr, addrlen, host, NI_MAXHOST, nullptr, 0,
1705	                     NI_NUMERICHOST);
1706	    if (rv == 0) {
1707	      if (found) {
1708	        A2_LOG_INFO(fmt("Found configured address: %s", host));
1709	      }
1710	      else {
1711	        A2_LOG_INFO(fmt("Not considered: %s", host));
1712	      }
1713	    }
1714	  }
1715	  A2_LOG_INFO(fmt("IPv4 configured=%d, IPv6 configured=%d", ipv4AddrConfigured,
1716	                  ipv6AddrConfigured));
1717	#else  // !HAVE_GETIFADDRS
1718	  A2_LOG_INFO("getifaddrs is not available. Assume IPv4 and IPv6 addresses"
1719	              " are configured.");
1720	#endif // !HAVE_GETIFADDRS
1721	}
