51	AsyncNameResolverMan::AsyncNameResolverMan()
52	    : numResolver_(0), resolverCheck_(0), ipv4_(true), ipv6_(true)
53	{
54	}
55	
56	AsyncNameResolverMan::~AsyncNameResolverMan() { assert(!resolverCheck_); }
57	
58	bool AsyncNameResolverMan::started() const
59	{
60	  for (size_t i = 0; i < numResolver_; ++i) {
61	    if (asyncNameResolver_[i]) {
62	      return true;
63	    }
64	  }
65	  return false;
66	}
67	
68	void AsyncNameResolverMan::startAsync(const std::string& hostname,
69	                                      DownloadEngine* e, Command* command)
70	{
71	  numResolver_ = 0;
72	  // Set IPv6 resolver first, so that we can push IPv6 address in
73	  // front of IPv6 address in getResolvedAddress().
74	  if (ipv6_) {
75	    startAsyncFamily(hostname, AF_INET6, e, command);
76	    ++numResolver_;
77	  }
78	  if (ipv4_) {
79	    startAsyncFamily(hostname, AF_INET, e, command);
80	    ++numResolver_;
81	  }
82	  A2_LOG_INFO(
83	      fmt(MSG_RESOLVING_HOSTNAME, command->getCuid(), hostname.c_str()));
84	}
85	
86	void AsyncNameResolverMan::startAsyncFamily(const std::string& hostname,
87	                                            int family, DownloadEngine* e,
88	                                            Command* command)
89	{
90	  asyncNameResolver_[numResolver_] =
91	      std::make_shared<AsyncNameResolver>(family, servers_);
92	  asyncNameResolver_[numResolver_]->resolve(hostname);
93	  setNameResolverCheck(numResolver_, e, command);
94	}
95	
96	void AsyncNameResolverMan::getResolvedAddress(
97	    std::vector<std::string>& res) const
98	{
99	  for (size_t i = 0; i < numResolver_; ++i) {
100	    if (asyncNameResolver_[i]->getStatus() ==
101	        AsyncNameResolver::STATUS_SUCCESS) {
102	      auto& addrs = asyncNameResolver_[i]->getResolvedAddresses();
103	      res.insert(std::end(res), std::begin(addrs), std::end(addrs));
104	    }
105	  }
106	  return;
107	}
108	
109	void AsyncNameResolverMan::setNameResolverCheck(DownloadEngine* e,
110	                                                Command* command)
111	{
112	  for (size_t i = 0; i < numResolver_; ++i) {
113	    setNameResolverCheck(i, e, command);
114	  }
115	}
116	
117	void AsyncNameResolverMan::setNameResolverCheck(size_t index, DownloadEngine* e,
118	                                                Command* command)
119	{
120	  if (asyncNameResolver_[index]) {
121	    assert((resolverCheck_ & (1 << index)) == 0);
122	    resolverCheck_ |= 1 << index;
123	    e->addNameResolverCheck(asyncNameResolver_[index], command);
124	  }
125	}
126	
127	void AsyncNameResolverMan::disableNameResolverCheck(DownloadEngine* e,
128	                                                    Command* command)
129	{
130	  for (size_t i = 0; i < numResolver_; ++i) {
131	    disableNameResolverCheck(i, e, command);
132	  }
133	}
134	
135	void AsyncNameResolverMan::disableNameResolverCheck(size_t index,
136	                                                    DownloadEngine* e,
137	                                                    Command* command)
138	{
139	  if (asyncNameResolver_[index] && (resolverCheck_ & (1 << index))) {
140	    resolverCheck_ &= ~(1 << index);
141	    e->deleteNameResolverCheck(asyncNameResolver_[index], command);
142	  }
143	}
144	
145	int AsyncNameResolverMan::getStatus() const
146	{
147	  size_t success = 0;
148	  size_t error = 0;
149	  bool ipv4Success = false;
150	  for (size_t i = 0; i < numResolver_; ++i) {
151	    switch (asyncNameResolver_[i]->getStatus()) {
152	    case AsyncNameResolver::STATUS_SUCCESS:
153	      ++success;
154	      if (asyncNameResolver_[i]->getFamily() == AF_INET) {
155	        ipv4Success = true;
156	      }
157	      break;
158	    case AsyncNameResolver::STATUS_ERROR:
159	      ++error;
160	      break;
161	    default:
162	      break;
163	    }
164	  }
165	  // If we got a IPv4 lookup response, we don't wait for a IPv6 lookup
166	  // response. This is because DNS servers may drop AAAA queries and we
167	  // have to wait for a long time before timeout. We don't do the
168	  // inverse, because, based on today's deployment of DNS servers,
169	  // almost all of them can respond to A queries just fine.
170	  if ((success && ipv4Success) || success == numResolver_) {
171	    return 1;
172	  }
173	  else if (error == numResolver_) {
174	    return -1;
175	  }
176	  else {
177	    return 0;
178	  }
179	}
