46	
47	void callback(void* arg, int status, int timeouts, ares_addrinfo* result)
48	{
49	  AsyncNameResolver* resolverPtr = reinterpret_cast<AsyncNameResolver*>(arg);
50	  if (status != ARES_SUCCESS) {
51	    resolverPtr->error_ = ares_strerror(status);
52	    resolverPtr->status_ = AsyncNameResolver::STATUS_ERROR;
53	    return;
54	  }
55	  for (auto ap = result->nodes; ap; ap = ap->ai_next) {
56	    char addrstring[NI_MAXHOST];
57	    auto rv = getnameinfo(ap->ai_addr, ap->ai_addrlen, addrstring,
58	                          sizeof(addrstring), nullptr, 0, NI_NUMERICHOST);
59	    if (rv == 0) {
60	      resolverPtr->resolvedAddresses_.push_back(addrstring);
61	    }
62	  }
63	  ares_freeaddrinfo(result);
64	  if (resolverPtr->resolvedAddresses_.empty()) {
65	    resolverPtr->error_ = "no address returned or address conversion failed";
66	    resolverPtr->status_ = AsyncNameResolver::STATUS_ERROR;
67	  }
68	  else {
69	    resolverPtr->status_ = AsyncNameResolver::STATUS_SUCCESS;
70	  }
71	}
