73	namespace {
74	void sock_state_cb(void* arg, ares_socket_t fd, int read, int write)
75	{
76	  auto resolver = static_cast<AsyncNameResolver*>(arg);
77	
78	  resolver->handle_sock_state(fd, read, write);
79	}
80	} // namespace
81	
82	void AsyncNameResolver::handle_sock_state(ares_socket_t fd, int read, int write)
83	{
84	  int events = 0;
85	
86	  if (read) {
87	    events |= EventPoll::EVENT_READ;
88	  }
89	
90	  if (write) {
91	    events |= EventPoll::EVENT_WRITE;
92	  }
93	
94	  auto it = std::find_if(
95	      std::begin(socks_), std::end(socks_),
96	      [fd](const AsyncNameResolverSocketEntry& ent) { return ent.fd == fd; });
97	  if (it == std::end(socks_)) {
98	    if (!events) {
99	      return;
100	    }
101	
102	    socks_.emplace_back(AsyncNameResolverSocketEntry{fd, events});
103	
104	    return;
105	  }
106	
107	  if (!events) {
108	    socks_.erase(it);
109	    return;
110	  }
111	
112	  (*it).events = events;
113	}
114	
115	AsyncNameResolver::AsyncNameResolver(int family, const std::string& servers)
116	    : status_(STATUS_READY), family_(family)
117	{
118	  ares_options opts{};
119	  opts.sock_state_cb = sock_state_cb;
120	  opts.sock_state_cb_data = this;
121	
122	  // TODO evaluate return value
123	  ares_init_options(&channel_, &opts, ARES_OPT_SOCK_STATE_CB);
124	
125	  if (!servers.empty()) {
126	    if (ares_set_servers_csv(channel_, servers.c_str()) != ARES_SUCCESS) {
127	      A2_LOG_DEBUG("ares_set_servers_csv failed");
128	    }
129	  }
130	}
131	
132	AsyncNameResolver::~AsyncNameResolver() { ares_destroy(channel_); }
133	
134	void AsyncNameResolver::resolve(const std::string& name)
135	{
136	  hostname_ = name;
137	  status_ = STATUS_QUERYING;
138	
139	  ares_addrinfo_hints hints{};
140	  hints.ai_family = family_;
141	
142	  ares_getaddrinfo(channel_, name.c_str(), nullptr, &hints, callback, this);
143	}
144	
145	ares_socket_t AsyncNameResolver::getFds(fd_set* rfdsPtr, fd_set* wfdsPtr) const
146	{
147	  ares_socket_t nfds = 0;
148	
149	  for (const auto& ent : socks_) {
150	    if (ent.events & EventPoll::EVENT_READ) {
151	      FD_SET(ent.fd, rfdsPtr);
152	      nfds = std::max(nfds, ent.fd + 1);
153	    }
154	
155	    if (ent.events & EventPoll::EVENT_WRITE) {
156	      FD_SET(ent.fd, wfdsPtr);
157	      nfds = std::max(nfds, ent.fd + 1);
158	    }
159	  }
160	
161	  return nfds;
162	}
163	
164	void AsyncNameResolver::process(fd_set* rfdsPtr, fd_set* wfdsPtr)
165	{
166	  for (const auto& ent : socks_) {
167	    ares_socket_t readfd = ARES_SOCKET_BAD;
168	    ares_socket_t writefd = ARES_SOCKET_BAD;
169	
170	    if (FD_ISSET(ent.fd, rfdsPtr) && (ent.events & EventPoll::EVENT_READ)) {
171	      readfd = ent.fd;
172	    }
173	
174	    if (FD_ISSET(ent.fd, wfdsPtr) && (ent.events & EventPoll::EVENT_WRITE)) {
175	      writefd = ent.fd;
176	    }
177	
178	    if (readfd != ARES_SOCKET_BAD || writefd != ARES_SOCKET_BAD) {
179	      process(readfd, writefd);
180	    }
181	  }
182	}
