131	std::shared_ptr<BackupConnectInfo>
132	InitiateConnectionCommand::createBackupIPv4ConnectCommand(
133	    const std::string& hostname, const std::string& ipaddr, uint16_t port,
134	    Command* mainCommand)
135	{
